"""Compression entry point for the VLA-JEPA LIBERO policy."""

from share_qkv import share_qkv


def group_by_width(blocks):
    """Group attention blocks that share an input width."""
    groups = {}
    for block in blocks:
        width = block.qkv.weight.shape[1]
        groups.setdefault(width, []).append(block)
    return groups


def compress(policy, calibration):
    """Tie the q/k/v projections of blocks that share a feature width."""
    for blocks in group_by_width(policy.attention_blocks()).values():
        keep = blocks[0]
        for block in blocks[1:]:
            share_qkv(block, keep.qkv.weight)
    return policy

