"""Policy rewrite: fill batches of two and protect the early-round budget."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from rsi.api import (
    GridPlan,
    GridPlanningContext,
    LLMDesignedMethod,
    SimResult,
    _budget_done,
    _record_curve,
    finalize_result,
)
from rsi.policies._plan import explicit_grid_plan


@dataclass
class _State:
    stagnant: int = 0
    best: float = 0.0
    opened: set[str] = field(default_factory=set)


class OptimalPolicy(LLMDesignedMethod):
    """Open up to three roots early, then spend two-probe batches on the best parent."""

    NAME = "OptimalPolicy"

    def __init__(self, config: dict[str, Any] | None = None) -> None:
        super().__init__(config)
        self.beta = float(self.config.get("beta", 0.5))

    def _schedule(self, beta: float) -> dict[str, float]:
        b = max(0.0, min(1.0, beta))
        return {
            "roots": 2.0 + 2.0 * b,
            "patience": 1.0 + 3.0 * b,
            "min_gain": 0.01 + 0.03 * (1.0 - b),
        }

    def solve(self, question: Any, budget: int | None = None) -> SimResult:
        res = SimResult()
        sched = self._schedule(self.beta)
        state = _State(best=question.baseline_score)
        while not _budget_done(question, budget):
            legal = question.legal_actions()
            if not legal:
                break
            roots = [c for c in question.legal_roots() if c not in state.opened]
            if roots and len(state.opened) < int(sched["roots"]):
                batch = roots[:2]
            else:
                batch = _frontier_batch(question, legal, sched["min_gain"])
            if not batch:
                break
            revealed = question.probe_batch(batch, on_reveal=lambda _: _record_curve(res, question))
            state.opened.update(batch)
            scores = [o.score for o in revealed if o.fail_class == "ok" and o.score is not None]
            if scores and max(scores) > state.best + sched["min_gain"]:
                state.best = max(scores)
                state.stagnant = 0
            else:
                state.stagnant += 1
                if state.stagnant >= int(sched["patience"]):
                    break
        return finalize_result(question, res)

    def plan_grid(self, context: GridPlanningContext) -> GridPlan:
        return explicit_grid_plan(context)


def _frontier_batch(question: Any, legal: list[str], min_gain: float) -> list[str]:
    """Two children of the best passing parent, ties broken by cell id."""
    observed = question.observed()
    best: tuple[float, str] | None = None
    for cell in legal:
        meta = question.meta(cell)
        parent = observed.get(meta.parent_id) if meta.parent_id else None
        if parent is None or parent.fail_class != "ok" or parent.score is None:
            continue
        if parent.score < min_gain:
            continue
        key = (parent.score, cell)
        if best is None or key > best:
            best = key
    if best is None:
        return legal[:2]
    parent_id = question.meta(best[1]).parent_id
    return [c for c in legal if question.meta(c).parent_id == parent_id][:2]

